16	// FakeMsg is a jetstream.Msg for unit-testing a consumer's message disposition
17	// without a live broker. Script the fields the handler reads (SubjectVal,
18	// DataVal, HeadersVal, Meta) and assert the terminal call it made (Acked,
19	// Termed, NakDelays, ...). Because jetstream.Msg is an interface — unlike the
20	// concrete *nats.Msg whose Ack/Nak/Term hit the wire — the disposition is now
21	// directly observable.
22	type FakeMsg struct {
23		SubjectVal string
24		DataVal    []byte
25		HeadersVal nats.Header
26		Meta       *jetstream.MsgMetadata
27		MetaErr    error
28	
29		Acked       bool
30		Termed      bool
31		NakDelays   []time.Duration
32		InProgressN int
33	}
